CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, name TEXT NOT NULL, platform TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), revoked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS pairing_challenges (id UUID PRIMARY KEY, user_code_hash TEXT NOT NULL, device_secret_hash TEXT NOT NULL, device_id TEXT NOT NULL, device_name TEXT NOT NULL, platform TEXT NOT NULL, account_id TEXT, expires_at TIMESTAMPTZ NOT NULL, approved_at TIMESTAMPTZ, consumed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS pairing_challenges_expires_idx ON pairing_challenges(expires_at);
CREATE TABLE IF NOT EXISTS device_sessions (id UUID PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE, access_token_hash TEXT NOT NULL UNIQUE, refresh_token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, profile_id TEXT NOT NULL, payload JSONB NOT NULL, position INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(account_id, profile_id));
CREATE TABLE IF NOT EXISTS sync_state (account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE, payload JSONB NOT NULL DEFAULT '{}'::jsonb, revision BIGINT NOT NULL DEFAULT 1, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
